using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Nethereum.Util;

namespace Nethereum.Npgsql.EntityFrameworkCore.MigrationTests.Ef8Fixture;

/// <summary>
/// Same model as Demo.Api's NumberContext. The migrations and snapshot next to it were generated by
/// EF Core 8.0.4 (see the ProductVersion annotation) and are kept as-is, so every test checks that
/// EF8-era migrations keep working under whichever EF Core version this assembly is built for.
/// </summary>
public class NumberContext : DbContext
{
    public NumberContext(DbContextOptions<NumberContext> options) : base(options)
    {
    }

    /// <summary>
    /// Optional extra model configuration, used by tests to simulate a model change
    /// (a new migration) on top of the EF8 snapshot.
    /// </summary>
    public Action<ModelBuilder>? ExtraModel { get; init; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<Number>()
            .Property(e => e.LargeNumber);

        modelBuilder.Entity<Number>()
            .Property(e => e.SecondLargeNumber)
            .HasDefaultValue(BigDecimal.Parse("1.5"));

        ExtraModel?.Invoke(modelBuilder);
    }

    public DbSet<Number> Numbers => Set<Number>();
}

/// <summary>Keeps the extended test model from sharing the cached base model.</summary>
public sealed class ExtraModelCacheKeyFactory : IModelCacheKeyFactory
{
    public object Create(DbContext context, bool designTime)
        => (context.GetType(), (context as NumberContext)?.ExtraModel is not null, designTime);
}
